mapper.update:
UPDATE sales_order_item
SET
    shipped_qty = shipped_qty + #{baseShippedQty},
    version = version + 1,
    updated_at = SYSTIMESTAMP,
    updated_by = #{updatedBy}
WHERE sales_order_item_id = #{salesOrderItemId}

    AND version = #{version}
AND shipped_qty + #{baseShippedQty} <= base_ordered_qty

UPDATE outbound
SET
    status = 'CONFIRMED',
    confirmed_at = SYSTIMESTAMP,
    confirmed_by = #{confirmedBy},
    updated_at = SYSTIMESTAMP,
    updated_by =#{confirmedBy}
WHERE outbound_id = #{outboundId}
    AND company_id = #{companyId}
    AND status = 'DRAFT'

mapper.select:
SELECT COUNT(*)
FROM warehouse w
WHERE w.warehouse_id = #{warehouseId}
AND w.company_id = #{companyId}
